<template>
  <view class="chat-page">
    <view class="chat-header"><text class="back" @tap="back">‹</text><view class="header-copy"><view class="header-title">{{ session?.title || '沟通会话' }}</view><view class="header-subtitle">{{ otherName || '邀请会话' }} · {{ syncing ? '同步中' : session?.guestId ? '沟通中' : '等待对方加入' }}</view></view><text class="more" @tap="showInfo = !showInfo">···</text></view>
    <view v-if="session?.creatorId === userId && !session.guestId" class="share-strip"><view><view class="share-title">邀请对方加入会话</view><view class="share-desc">生成有效期 7 天的微信分享卡片</view></view><button v-if="!invitePath" class="share-button" :loading="inviting" @tap="prepareInvite">生成分享卡片</button><button v-else class="share-button" open-type="share">分享给对方</button></view>
    <view v-else-if="session?.guestId" class="participant-strip"><view class="participant-avatar">{{ otherName?.slice(0, 1) || '协' }}</view><view><view class="participant-title">{{ otherName }} · 已加入</view><view class="participant-subtitle">消息会保存在当前会话中</view></view></view>
    <view v-if="showInfo" class="info-panel"><text>会话创建者：{{ session?.creatorName || '加载中' }}</text><text>邀请状态：{{ session?.guestId ? '对方已加入' : '等待对方加入' }}</text><text v-if="invitePath">邀请码有效期：7 天</text></view>
    <view v-if="error" class="error-box chat-error" @tap="load">{{ error }} · 点击重试</view>
    <scroll-view scroll-y class="timeline" :scroll-into-view="scrollTarget" scroll-with-animation>
      <view v-if="!messages.length && !error" class="empty-chat"><view class="empty-icon">聊</view><text>{{ session?.guestId ? '会话已准备好，说说这次的设计需求吧。' : '分享会话后，对方会直接来到这里。' }}</text></view>
      <view v-for="item in messages" :key="item.id" class="message" :class="{ mine: item.senderId === userId }">
        <text class="sender">{{ item.senderName }}</text>
        <view v-if="intakeCard(item) && intakeCard(item)!.kind !== 'decision'" class="workflow-card">
          <text class="card-kicker">{{ cardLabel(intakeCard(item)!) }}</text>
          <view class="card-title">{{ intakeCard(item)!.title }}</view>
          <view v-if="intakeCard(item)!.description" class="card-description">{{ intakeCard(item)!.description }}</view>
          <template v-if="intakeCard(item)!.kind === 'form'">
            <view class="card-meta">{{ fieldCount(intakeCard(item)!) }} 项需求 · {{ submissionFor(intakeCard(item)!.id) ? '已提交' : '待填写' }}</view>
            <button class="card-action" @tap="fillForm(intakeCard(item)!)">{{ submissionFor(intakeCard(item)!.id) ? '查看 / 更新需求资料' : '填写需求资料' }} →</button>
          </template>
          <template v-else-if="intakeCard(item)!.kind === 'submission'">
            <view v-for="entry in answerPreview(intakeCard(item)!)" :key="entry.label" class="answer-row"><text class="answer-label">{{ entry.label }}</text><text class="answer-value">{{ entry.value }}</text></view>
            <view class="card-meta">资料已提交，双方可据此发起需求确认。</view>
          </template>
          <template v-else-if="intakeCard(item)!.kind === 'confirmation'">
            <view class="card-description">纳入需求资料：{{ formNames(intakeCard(item)!) }}</view>
            <view class="card-meta">{{ confirmationStatus(intakeCard(item)!) }}</view>
            <button v-if="!myDecision(intakeCard(item)!.id)" class="card-action" @tap="confirmRequirement(intakeCard(item)!)">确认需求内容</button>
            <view v-else class="decision-done">{{ myDecision(intakeCard(item)!.id) === 'confirmed' ? '你已确认' : '你已提出修改' }}</view>
          </template>
        </view>
        <view v-else-if="cardDecision(item)" class="bubble"><text>{{ decisionText(cardDecision(item)!) }}</text></view>
        <view v-else class="bubble"><text>{{ item.body }}</text></view>
        <text v-if="item.senderId === userId" class="saved">已保存</text>
      </view>
      <view id="bottom" class="chat-bottom" />
    </scroll-view>
    <view class="composer"><view class="composer-tools"><view class="tool-pill" @tap="showTools = true">＋ 工具</view><view class="tool-pill primary-tool" @tap="openCombo">组合发单</view><view class="tool-pill" @tap="openStandard">标准表单</view><view v-if="submittedForms.length" class="tool-pill" @tap="createConfirmation">需求确认</view></view><view class="composer-row"><textarea v-model="draft" class="message-input" auto-height maxlength="5000" placeholder="沟通需求、补充说明…" /><button class="send" :loading="sending" :disabled="sending || !draft.trim()" @tap="send">发送</button></view></view>

    <view v-if="showTools" class="modal-mask" @tap="showTools = false"><view class="tool-modal" @tap.stop><view class="modal-heading"><text class="modal-title">会话工具</text><text class="modal-close" @tap="showTools = false">×</text></view><view class="tool-option" @tap="openCombo(); showTools = false"><text class="tool-option-icon">组</text><view><text class="tool-option-title">组合发单</text><text class="tool-option-hint">跨业务类别组合需求字段，发送给会话成员填写</text></view></view><view class="tool-option" @tap="openStandard(); showTools = false"><text class="tool-option-icon">单</text><view><text class="tool-option-title">标准表单</text><text class="tool-option-hint">选择一类设计需求，快速发送完整表单</text></view></view><view v-if="submittedForms.length" class="tool-option" @tap="createConfirmation(); showTools = false"><text class="tool-option-icon">确</text><view><text class="tool-option-title">发起需求确认</text><text class="tool-option-hint">把已提交的需求资料整理成双方确认项</text></view></view></view></view>

    <view v-if="comboOpen" class="modal-mask" @tap="comboOpen = false"><view class="tool-modal combo-modal" @tap.stop><view class="modal-heading"><view><text class="modal-title">组合发单</text><text class="modal-subtitle">选择一个或多个业务类别，再勾选需要填写的问题。</text></view><text class="modal-close" @tap="comboOpen = false">×</text></view><picker :range="presets" range-key="name" :value="presetIndex" @change="selectPreset"><view class="preset-picker">{{ currentPreset.name }}<text>⌄</text></view></picker><view class="field-list"><view v-for="section in currentPreset.sections" :key="section.title" class="field-section"><text class="section-name">{{ section.title }}</text><label v-for="field in section.fields" :key="field.key" class="field-choice"><checkbox :checked="isFieldSelected(currentPreset.id, field.key)" color="#2563eb" @tap="toggleField(currentPreset.id, field.key)"/><text>{{ field.label }}{{ field.required ? ' · 必填' : '' }}</text></label></view></view><view class="selected-count">已选 {{ selectedCount }} 项{{ comboError ? ` · ${comboError}` : '' }}</view><view class="modal-actions"><button class="secondary" :disabled="sending" @tap="comboOpen = false">取消</button><button class="primary" :loading="sending" :disabled="sending || !selectedCount" @tap="sendCombo">发送组合表单</button></view></view></view>

    <view v-if="standardOpen" class="modal-mask" @tap="standardOpen = false"><view class="tool-modal" @tap.stop><view class="modal-heading"><view><text class="modal-title">标准发单</text><text class="modal-subtitle">选择一种需求类型，发送完整标准表单。</text></view><text class="modal-close" @tap="standardOpen = false">×</text></view><picker :range="presets" range-key="name" :value="standardIndex" @change="selectStandard"><view class="preset-picker">{{ standardPreset.name }}<text>⌄</text></view></picker><view class="card-description">{{ standardPreset.description }}</view><view class="modal-actions"><button class="secondary" :disabled="sending" @tap="standardOpen = false">取消</button><button class="primary" :loading="sending" :disabled="sending" @tap="sendStandardForm">发送标准表单</button></view></view></view>

    <view v-if="fillCard" class="modal-mask" @tap="fillCard = null"><view class="tool-modal fill-modal" @tap.stop><view class="modal-heading"><view><text class="modal-title">{{ fillCard.title }}</text><text class="modal-subtitle">提交后会在会话中留存，双方可继续补充。</text></view><text class="modal-close" @tap="fillCard = null">×</text></view><form-fields v-model="formAnswers" :fields="fillCard.fields"/><view v-if="formError" class="error-text">{{ formError }}</view><view class="modal-actions"><button class="secondary" :disabled="sending" @tap="fillCard = null">取消</button><button class="primary" :loading="sending" :disabled="sending" @tap="submitIntakeForm">提交需求</button></view></view></view>
  </view>
</template>
<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { onLoad, onShow, onHide, onUnload, onShareAppMessage } from '@dcloudio/uni-app';
import { ORDER_FORM_PRESETS, type FormAnswers, type FormField } from '@design-review/shared';
import { api, getSession, requireSession, uuid, type IntakeMessage, type IntakeSession } from '../../lib/api';
import FormFields from '../../components/form-fields.vue';
import { defaultAnswers } from '../../lib/forms';
type IntakeCard = { version: 1; id: string; title: string; description?: string } & ({ kind: 'form'; fields: FormField[] } | { kind: 'submission'; formId: string; answers: FormAnswers } | { kind: 'confirmation'; formIds: string[] } | { kind: 'decision'; confirmationId: string; decision: 'confirmed' | 'changes'; note: string });
const CARD_PREFIX = 'COZI_INTAKE_CARD_V1:';
const id = ref(''); const session = ref<IntakeSession | null>(null); const messages = ref<IntakeMessage[]>([]); const draft = ref(''); const error = ref(''); const inviting = ref(false); const sending = ref(false); const syncing = ref(false); const invitePath = ref(''); const scrollTarget = ref(''); const userId = ref(''); const showInfo = ref(false); let cursor = 0; let timer: ReturnType<typeof setInterval> | undefined; let active = false;
const showTools = ref(false); const comboOpen = ref(false); const comboError = ref(''); const presetIndex = ref(0); const standardOpen = ref(false); const standardIndex = ref(0); const selections = ref<Record<string, string[]>>({}); const fillCard = ref<Extract<IntakeCard, { kind: 'form' }> | null>(null); const formAnswers = ref<FormAnswers>({}); const formError = ref('');
const presets = ORDER_FORM_PRESETS; const currentPreset = computed(() => presets[presetIndex.value] || presets[0]); const standardPreset = computed(() => presets[standardIndex.value] || presets[0]);
const otherName = computed(() => session.value?.creatorId === userId.value ? session.value?.guestName : session.value?.creatorName);
const intakeCards = computed(() => messages.value.map(message => ({ message, card: parseIntakeCard(message.body) })).filter((entry): entry is { message: IntakeMessage; card: IntakeCard } => !!entry.card));
const submittedForms = computed(() => intakeCards.value.filter((entry): entry is { message: IntakeMessage; card: Extract<IntakeCard, { kind: 'submission' }> } => entry.card.kind === 'submission'));
const selectedCount = computed(() => Object.values(selections.value).reduce((total, keys) => total + keys.length, 0));
const draftKey = () => `cozi-intake-draft:${userId.value}:${id.value}`;
onLoad(options => { id.value = String(options?.id || ''); userId.value = getSession()?.user.id || ''; draft.value = uni.getStorageSync(draftKey()) || ''; });
watch(draft, value => { if (id.value && userId.value) { try { uni.setStorageSync(draftKey(), value); } catch { error.value = '草稿未能保存在本机'; } } });
onShow(() => { if (!requireSession()) return; userId.value = getSession()?.user.id || ''; active = true; void load(); if (!timer) timer = setInterval(() => { void load(); }, 5000); });
function stop() { active = false; if (timer) clearInterval(timer); timer = undefined; }
onHide(stop); onUnload(stop);
onShareAppMessage(() => ({ title: `邀请你加入沟通：${session.value?.title || '项目需求'}`, path: invitePath.value || '/pages/sessions/index' }));
async function load() {
  if (!id.value || !active || syncing.value) return;
  syncing.value = true;
  try {
    session.value = await api.intakeSession(id.value);
    let more = true; let changed = false;
    while (more && active) { const page = await api.intakeMessages(id.value, cursor); if (page.messages.length) { cursor = page.messages[page.messages.length - 1].seq; const known = new Set(messages.value.map(item => item.id)); messages.value.push(...page.messages.filter(item => !known.has(item.id))); changed = true; } more = page.hasMore && !!page.messages.length; }
    error.value = ''; if (changed) { scrollTarget.value = ''; await nextTick(); scrollTarget.value = 'bottom'; }
  } catch (cause) { error.value = cause instanceof Error ? cause.message : '同步失败'; }
  finally { syncing.value = false; }
}
async function prepareInvite() { if (inviting.value) return; inviting.value = true; try { const result = await api.intakeInvite(id.value); invitePath.value = result.path; } catch (cause) { error.value = cause instanceof Error ? cause.message : '生成邀请失败'; } finally { inviting.value = false; } }
async function send() { const body = draft.value.trim(); if (!body || sending.value) return; sending.value = true; try { await api.sendIntakeMessage(id.value, uuid(), body); draft.value = ''; uni.removeStorageSync(draftKey()); await load(); } catch (cause) { error.value = cause instanceof Error ? cause.message : '发送失败，消息仍保留在输入框中'; } finally { sending.value = false; } }
function parseIntakeCard(body: string): IntakeCard | null { if (!body.startsWith(CARD_PREFIX)) return null; try { const value = JSON.parse(body.slice(CARD_PREFIX.length)); return value?.version === 1 && typeof value.id === 'string' && ['form', 'submission', 'confirmation', 'decision'].includes(value.kind) ? value as IntakeCard : null; } catch { return null; } }
function intakeCard(message: IntakeMessage) { return parseIntakeCard(message.body); }
function cardLabel(card: IntakeCard) { return ({ form: '需求表单', submission: '需求资料', confirmation: '需求确认', decision: '确认记录' })[card.kind]; }
function submissionFor(formId: string) { return [...submittedForms.value].reverse().find(entry => entry.card.formId === formId); }
function answerPreview(card: Extract<IntakeCard, { kind: 'submission' }>) { const form = intakeCards.value.find(entry => entry.card.kind === 'form' && entry.card.id === card.formId)?.card; if (form?.kind !== 'form') return Object.entries(card.answers).slice(0, 5).map(([label, value]) => ({ label, value: answerText(value) })); return form.fields.filter(field => field.kind !== 'section' && card.answers[field.key] !== undefined && card.answers[field.key] !== '').slice(0, 6).map(field => ({ label: field.label, value: answerText(card.answers[field.key]) })); }
function answerText(value: unknown) { return Array.isArray(value) ? value.join('、') : typeof value === 'object' && value ? JSON.stringify(value) : String(value ?? ''); }
function fieldCount(card: IntakeCard) { return card.kind === 'form' ? card.fields.filter(field => field.kind !== 'section').length : 0; }
function formNames(card: IntakeCard) { if (card.kind !== 'confirmation') return ''; return card.formIds.map(formId => intakeCards.value.find(entry => entry.card.kind === 'form' && entry.card.id === formId)?.card.title || '已提交表单').join('、'); }
function fillForm(card: IntakeCard) { if (card.kind !== 'form') return; const prior = [...submittedForms.value].reverse().find(entry => entry.card.formId === card.id && entry.message.senderId === userId.value); fillCard.value = card; formAnswers.value = { ...defaultAnswers(card.fields), ...(prior?.card.answers || {}) }; formError.value = ''; }
function selectPreset(event: { detail: { value: string | number } }) { presetIndex.value = Number(event.detail.value); }
function selectStandard(event: { detail: { value: string | number } }) { standardIndex.value = Number(event.detail.value); }
function isFieldSelected(presetId: string, key: string) { return (selections.value[presetId] || []).includes(key); }
function toggleField(presetId: string, key: string) { const keys = selections.value[presetId] || []; selections.value = { ...selections.value, [presetId]: keys.includes(key) ? keys.filter(item => item !== key) : [...keys, key] }; comboError.value = ''; }
function openCombo() { selections.value = {}; presetIndex.value = 0; comboError.value = ''; comboOpen.value = true; }
function openStandard() { standardIndex.value = 0; standardOpen.value = true; }
function fieldsFor(presetId: string, selectedKeys: string[]) { const preset = presets.find(item => item.id === presetId)!; const fields: FormField[] = []; for (const section of preset.sections) { const picked = section.fields.filter(field => selectedKeys.includes(field.key)); if (!picked.length) continue; fields.push({ key: `${presetId}_section_${fields.length + 1}`, label: section.title, kind: 'section', required: false, width: 100 }); fields.push(...picked.map(field => ({ key: `${presetId}_${field.key}`, label: field.label, kind: field.kind, required: Boolean(field.required), placeholder: field.placeholder || '', width: field.kind === 'textarea' ? 100 : 50, ...(field.options ? { options: field.options.map(value => ({ label: value, value })) } : {}) } as FormField))); } return fields; }
async function sendIntakeCard(card: IntakeCard) { const body = `${CARD_PREFIX}${JSON.stringify(card)}`; if (body.length > 4900) throw new Error('所选内容过多，请减少题目后再发送'); await api.sendIntakeMessage(id.value, uuid(), body); await load(); }
async function sendCombo() { if (!selectedCount.value || sending.value) return; sending.value = true; comboError.value = ''; try { const fields = Object.entries(selections.value).filter(([, keys]) => keys.length).flatMap(([presetId, keys]) => fieldsFor(presetId, keys)); const titles = Object.keys(selections.value).filter(key => selections.value[key].length).map(key => presets.find(item => item.id === key)?.name); await sendIntakeCard({ version: 1, id: uuid(), kind: 'form', title: `组合需求表单 · ${titles.join(' + ')}`, description: '请会话成员填写选中的需求问题。', fields }); comboOpen.value = false; } catch (cause) { comboError.value = cause instanceof Error ? cause.message : '发送失败'; } finally { sending.value = false; } }
async function sendStandardForm() { if (sending.value) return; const preset = standardPreset.value; sending.value = true; try { await sendIntakeCard({ version: 1, id: uuid(), kind: 'form', title: preset.name, description: preset.description, fields: fieldsFor(preset.id, preset.sections.flatMap(section => section.fields.map(field => field.key))) }); standardOpen.value = false; } catch (cause) { error.value = cause instanceof Error ? cause.message : '发送表单失败'; } finally { sending.value = false; } }
async function submitIntakeForm() { const card = fillCard.value; if (!card || sending.value) return; const missing = card.fields.find(field => field.required && field.kind !== 'section' && !String(formAnswers.value[field.key] ?? '').trim()); if (missing) { formError.value = `请填写「${missing.label}」`; return; } sending.value = true; formError.value = ''; try { await sendIntakeCard({ version: 1, id: uuid(), kind: 'submission', formId: card.id, title: card.title, answers: formAnswers.value }); fillCard.value = null; } catch (cause) { formError.value = cause instanceof Error ? cause.message : '提交失败'; } finally { sending.value = false; } }
async function createConfirmation() { if (!submittedForms.value.length || sending.value) return; const formIds = [...new Set(submittedForms.value.map(entry => entry.card.formId))]; sending.value = true; try { await sendIntakeCard({ version: 1, id: uuid(), kind: 'confirmation', title: '设计需求确认', formIds }); } catch (cause) { error.value = cause instanceof Error ? cause.message : '发起确认失败'; } finally { sending.value = false; } }
function decisionEntries(confirmationId: string) { return intakeCards.value.filter((entry): entry is { message: IntakeMessage; card: Extract<IntakeCard, { kind: 'decision' }> } => entry.card.kind === 'decision' && entry.card.confirmationId === confirmationId); }
function myDecision(confirmationId: string) { return [...decisionEntries(confirmationId)].reverse().find(entry => entry.message.senderId === userId.value)?.card.decision; }
function confirmationStatus(card: IntakeCard) { if (card.kind !== 'confirmation') return ''; const latest = new Map<string, 'confirmed' | 'changes'>(); for (const entry of decisionEntries(card.id)) latest.set(entry.message.senderId, entry.card.decision); const people = [session.value?.creatorId, session.value?.guestId].filter((value): value is string => Boolean(value)); const confirmed = people.filter(person => latest.get(person) === 'confirmed').length; return people.length === 2 && confirmed === 2 ? '双方已确认 · 需求内容可进入设计' : `待双方确认 · 已确认 ${confirmed}/${people.length || 2}`; }
function confirmRequirement(card: IntakeCard) { if (card.kind !== 'confirmation' || myDecision(card.id)) return; uni.showActionSheet({ itemList: ['确认无误', '需要补充'], success: result => { const decision = result.tapIndex === 0 ? 'confirmed' : 'changes'; if (decision === 'changes') { uni.showModal({ title: '说明需要补充的内容', editable: true, placeholderText: '请填写需要调整的内容', success: modal => { if (modal.confirm && modal.content?.trim()) void sendDecision(card.id, decision, modal.content.trim()); } }); } else void sendDecision(card.id, decision, ''); } }); }
async function sendDecision(confirmationId: string, decision: 'confirmed' | 'changes', note: string) { sending.value = true; try { await sendIntakeCard({ version: 1, id: uuid(), kind: 'decision', title: '需求确认记录', confirmationId, decision, note }); } catch (cause) { error.value = cause instanceof Error ? cause.message : '确认未能保存'; } finally { sending.value = false; } }
function cardDecision(message: IntakeMessage) { const card = parseIntakeCard(message.body); return card?.kind === 'decision' ? card : null; }
function decisionText(card: Extract<IntakeCard, { kind: 'decision' }>) { return `${card.decision === 'confirmed' ? '已确认需求内容' : '需要补充需求'}${card.note ? `：${card.note}` : ''}`; }
function back() { uni.navigateBack({ fail: () => uni.switchTab({ url: '/pages/sessions/index' }) }); }
</script>
